public class GJChronology_hashCode_TriageGen0Test {





    @Test
    public void testHashCodeDifferentZones() {
        GJChronology utc = GJChronology.getInstanceUTC();
        GJChronology zone1 = GJChronology.getInstance(DateTimeZone.forID("UTC"));
        GJChronology zone2 = GJChronology.getInstance(DateTimeZone.forID("Asia/Tokyo"));

        assertEquals("UTC instances should have same hashCode", utc.hashCode(), zone1.hashCode());
        assertNotEquals("Different time zones should result in different hashCodes", utc.hashCode(), zone2.hashCode());
    }






}

